return {
    { title = "What Swarmed is", pages = {
        { title = "Introduction", blocks = {
            { p = "Swarmed is a top-down (isometric) arena roguelite made in LÖVE2D (Lua). You play one arthropod (a beetle, spider, scorpion, crustacean, centipede, mantis, dragonfly and so on) holding off endless hordes of ants, and later bees, wasps, hornets and termites. A run is fifteen waves across three maps, ending with crowned queens and the Empress." },
        } },
        { title = "The pillars", blocks = {
            { p = "These were set by Ozy at the start (26 October 2026) and every system since has been checked against them." },
            { p = "Pillar: What it means in the game", color = "accent" },
            { p = "Warriors-style mass kills: Hundreds of ants on screen, attacks that mow down lines and rings, bodies flying, hitstop and slow motion on big moments, a frenzy super move." },
            { p = "Brotato-style builds: Stats everywhere. Items, level-up cards, skill trees, keepsakes and artifacts all change stats or rules, so every run builds the bug differently." },
            { p = "Risk of Rain 2-style procs: Items fire effects on triggers (hit, kill, hurt, dash, dodge, wave start, eat, every frame). Procs can chain, and every wave makes them more likely." },
            { p = "Cute, crunchy pixel art that stays fast: Small pixels with rich shading, a dusky natural palette, real-world bugs. The renderer batches everything so 1,500 enemies still run." },
            { p = "Easy controls: Move, attack (or auto attack), special, dash. Everything else is optional. Works on keyboard, controller and touch." },
            { p = "Being overwhelmed: Every ant touching you bites on its own timer, with no invulnerability after a hit. The more ants on you, the more it hurts." },
        } },
        { title = "Design rules that run through everything", blocks = {
            { p = "- Data first. Every enemy, bug, item, map, event, mode and achievement is a Lua file in content/ that returns a table. Dropping a file in a folder adds it to the game. No lists to update, no engine code to touch. Each folder has a commented _template.lua." },
            { p = "- One file is one idea. A behaviour, an attack or a dash lives in one file with a header comment that explains it in plain words. That header is what this wiki quotes." },
            { p = "- Teach one thing at a time. Waves introduce one new species each. Gentle Start holds whole systems back over the first runs. Every new thing gets a short card the first time it appears." },
            { p = "- Never make it feel unfair. Wind-ups are telegraphed, hazards draw warning lanes, freezes are rare, stage hazards hurt the ants too, and nothing holds a wave up except living enemies." },
            { p = "- No repeats. Ozy dislikes moves or items that feel like copies of each other. Every bug's special and dash is its own, and new content is checked against what exists." },
            { p = "- Comfort is a setting, the game is not. Lighting looks, camera, HUD size, hints, slow motion, hitstop and so on each have their own switch, and presets set them in one press. Anything that changes how the game plays (events, gambles, parasites, pacing, difficulty) is a run rule that only a mode or a Custom Waves set can change, so the main game is the same for everyone." },
            { p = "- Not \"made by AI\". Ozy pushed back twice on things that looked generic (the old inventory, cluttered screens). The answer was one shared theme (src/ui/theme.lua), one art style, and less text." },
        } },
        { title = "The game in numbers", blocks = {
            { p = "Content: Count", color = "accent" },
            { p = "Playable bugs: 26 (8 open from the start)" },
            { p = "Enemies: 93, in 5 families (ants, bees, wasps, hornets, termites), including 24 queens and bosses" },
            { p = "Enemy behaviours (AI files): 69" },
            { p = "Items: 115 (13 of them only made by molting)" },
            { p = "Level-up cards: 43" },
            { p = "Skill trees: 26, plus 7 kin branches" },
            { p = "Maps: 10 (4 bought with amber)" },
            { p = "Game modes: 14" },
            { p = "Mid-wave events / stage hazards and boss encounters: 11 / 3" },
            { p = "Achievements: 123" },
            { p = "Settings: 140+" },
            { p = "Lua code: about 53,000 lines in src/, plus content" },
        } },
        { title = "How a run feels, start to finish", blocks = {
            { p = "1. Title screen. A live demo fight plays behind the menu. Play opens mode select (map, mode, keepsake, artifacts), then the bug select grid." },
            { p = "2. Wave 1. Plain worker ants march in as snaking columns from two sides and break into a ring around you. You attack, dash and use your special. Kills spill nectar beads." },
            { p = "3. Levelling. XP fills fast (the first level is about ten kills). Each level opens three stat cards right away; skipping a pick banks a skill point instead." },
            { p = "4. Wave clear. Every bead flies to you. A reward bloom sprouts beside you; walk into it to pick one of three items. The bag is a shaped-item puzzle where everything counts." },
            { p = "5. Waves 2 to 4. One new species per wave, each introduced alone under a \"NEW SPECIES\" card. Wave modifiers, mini-goals, events, map gambles and route tunnels join over the first few runs." },
            { p = "6. Wave 5. A queen arrives with a royal guard; she lays broods until she dies. Clearing her wave can molt touching items into stronger ones. The run then travels to the next map (act 2)." },
            { p = "7. Waves 6 to 14. Bees, wasps, termites, elites, named champions, stage hazards (a sparrow, a giant anteater), the shop, cursed items, proc chains filling the screen." },
            { p = "8. Wave 15. Crowned queens one after another, then the Empress. Win, then keep going (the bag grows a row) or take on the Final Swarm." },
            { p = "9. After the run. Amber is paid out for the Burrow (new maps, modes, item packs, artifacts, keepsakes), records and achievements update, unlock goals tick forward." },
        } },
        { title = "How to run it", blocks = {
            { p = "Install LÖVE 11.4 or newer, then from the game folder:" },
            { p = "love .                      # play\nlove . --sandbox            # straight into the sandbox\nlove . --selftest           # automated smoke test + horde benchmark, then quits\nlove . --selftest --<part>  # one part of the test (see the Tools chapter)\nlove . --roster             # every bug's 3D model walking in place\nlove . --anims              # attack animation viewer\nlove . --profile            # scripted massacre, prints where frame time goes\nlove . --balance            # a bot plays runs with several bugs and reports how far each gets\nlove . --makeicon           # repaints the game icon from the game's own models", color = "dim" },
            { p = "bash tools/build_web.sh builds the browser version (love.js) plus swarmed.love; the web build runs plain Lua 5.1, so the code avoids goto and LuaJIT-only libraries." },
        } },
        { title = "Where the code lives", blocks = {
            { p = "The repository is github.com/Omnilax/swarmed; the repo root is the game folder." },
            { p = "main.lua, conf.lua      boot, LÖVE callbacks, launch flags\nsrc/core/               registry, settings, input, touch, audio, music, screen, state stack,\n                        iso projection, spatial hash, event bus, Discord pipe\nsrc/config/             tunable numbers and tables: stats, settings schema, rarities, tags,\n                        categories, danger, unlocks, amber, keepsakes, rewards, shop, ...\nsrc/game/               the simulation: world, player, enemies, combat, spawner, pacing,\n                        director, items, skills, economy, rewards, saves, records, ...\nsrc/gfx/                sprite atlas, 3D models and animation, particles, ground, lighting,\n                        shading, painted pictures (paint, propart, beasts, antlion)\nsrc/ui/                 theme, menu widget, HUD, run HUD, palette, inspect\nsrc/states/             every screen (menu, mode select, bug select, game, bag, shop, ...)\nsrc/debug/              developer console, sandbox, catalogues, selftests, profiler, bot\ncontent/                all game content, one file per thing\ntools/                  Python sprite/icon generators, web build scripts\ndocs/                   PLAN.md (roadmap), CUSTOM_BUGS.md (Bug Creator reference)\nassets/                 fonts (Pixelify Sans), icon", color = "dim" },
        } },
        { title = "How this documentation is made", blocks = {
            { p = "The wiki volumes (Playable Bugs, Enemies, Items, World, Reference) are generated from the game itself, not written by hand. A small dump step loads every content registry exactly as the game does, writes it out with the pictures of every bug, enemy and item icon, and reads the comment block at the top of each content file. So every entry here matches the code it came from, and the set can be rebuilt after any change. This volume and the Style Guide are written from the code, the README and the design history." },
            { p = "This edition documents the code on the parasites / run rules branch (PR 45, on top of PRs 41, 43 and 44). A few features described in the hand-written chapters come from pull requests that were still open beside it (37 new items, 38 bug select grid, 39 new level-up cards, 40 Unlock Everything, 42 game icon and Discord status); the generated wiki pages list only what is in this build." },
            { p = "The same pages are in the game: Field Guide > Wiki (src/states/wiki.lua) writes every bug, enemy, item, card, map, event, mode and progression page live from the content, and its Design section is these chapters (docs/wiki/*.md, turned into src/config/wiki_notes.lua by tools/make_wiki_notes.py)." },
        } },
    } },
    { title = "The engine", pages = {
        { title = "Introduction", blocks = {
            { p = "Swarmed has no third-party engine or library besides LÖVE itself. Everything (the content system, the renderer's batching, the synthesised audio, the Discord pipe) is in the repository. This chapter walks through it in the order the game uses it: boot, the frame loop, the world, then each subsystem." },
        } },
        { title = "Boot sequence (main.lua)", blocks = {
            { p = "love.load(args) turns the launch arguments into a set of flags and then, in order:" },
            { p = "1. Settings load from settings.lua in the save folder (src/core/settings.lua, validated against src/config/settings_schema.lua). --dev forces Developer Mode on." },
            { p = "2. Screen sets up the low-resolution world canvas (960x540 by default, Settings > Video > Pixel Resolution) and its scaling to the window (src/core/screen.lua)." },
            { p = "3. Input binds actions to keys, mouse buttons, gamepad buttons and touch (src/core/input.lua, src/core/touch.lua)." },
            { p = "4. Content.load() fills every registry from content/ and cross-checks references (below)." },
            { p = "5. Records load, and cosmetic rewards from earned achievements are re-applied." },
            { p = "6. Test guards. Under --selftest, --profile and --balance, saves are switched off (records, prefs, run save, custom bugs go to a separate folder), every lock is open (unless --locked), hints, Gentle Start and act travel are off. Tests never touch the player's save." },
            { p = "7. Music starts rendering its stems (a slice per frame, cached as WAV files in music/). Presence (Discord) starts if possible." },
            { p = "8. Sprites.build bakes every sprite into one texture atlas (about 2048x14,000 px, ~19,000 pieces, ~2 s)." },
            { p = "9. Custom bugs from the Bug Creator load after the atlas (their own art is built as small separate images)." },
            { p = "10. The first state is pushed: the title menu, or the sandbox / roster / animation viewer / icon maker / profiler / balance bot / selftest depending on the flags." },
            { p = "love.run is the default LÖVE loop plus an optional frame cap when VSync is off. love.update and love.draw forward to the state stack; Feedback.update (music, hints, markers) and the selftest runner hook in beside it. F12 saves a screenshot, a dropped .lua file goes to the Bug Creator, and closing the window mid-run saves the run so it can be resumed." },
        } },
        { title = "The state stack (src/core/state.lua)", blocks = {
            { p = "Every screen is a state object with optional methods (enter, leave, resume, update, draw, input callbacks, resize, focus). State.switch replaces the stack, State.push / State.pop layer screens. A state with transparent = true (pause, bag, level-up, item choice) draws the state below it, dimmed to about 70% black. Every full-screen change fades in from the background colour, so screens never pop." },
            { p = "The arena itself is src/states/game.lua, which owns one World in \"run\" mode (a real run) or \"sandbox\" mode (developer playground, also used for the title-screen demo, the bug select preview and the Bug Creator test arena)." },
        } },
        { title = "Content and registries (src/content.lua, src/core/registry.lua)", blocks = {
            { p = "A Registry holds one kind of content: byId, an ordered list, a schema (required fields, defaults, an optional validate(def)). loadDirectory(\"content/<kind>\") loads every .lua file that does not start with _; a file returns one definition (its id defaults to the file name) or a list of them. order fields sort lists for menus." },
            { p = "Load order matters only where one kind reads another while validating: sprites, behaviours, attacks, dashes, elites, enemies, characters, skill branches, skill trees, items, stages, bosses, events, props, mechanics, wave modifiers, modes, weather, skins, decor, frenzies, streaks, goals, routes, level cards, pickups, artifacts, molts, then achievements last (several achievement files generate entries from the other registries, one per bug, family, elite and mode)." },
            { p = "After everything is loaded, crossCheck() verifies every reference: an enemy's sprite and behaviour, a character's sprite, model parts, attack, special, dash and starting items, every item's icon, every stage's mechanic, props and fauna keys, every mode's enemy lists and scripted waves, every molt recipe. One bad id stops the game at start-up with a list of every problem, so broken content never reaches a run." },
            { p = "To add a new kind of content: add a Registry in src/content.lua, add it to Content.order, make the folder with a _template.lua. To add a piece of content: add one file." },
        } },
        { title = "The frame (World:update)", blocks = {
            { p = "src/game/world.lua (about 1,700 lines) is one arena run: player, enemies, effects, camera and the spatial hash. Each frame:" },
            { p = "1. Time. dt is scaled by the world's time scale, the Game Speed setting, Hold To Inspect and the reward slow motion. During hitstop only the camera updates." },
            { p = "2. Atmosphere. Lighting, shading and ambience tick; a pending Highlight Shot is captured." },
            { p = "3. Deaths become visible. Last frame's kills (recentDeaths) are handed to behaviours that react to deaths nearby (big-headed majors rallying, Africanized bees getting angrier)." },
            { p = "4. Spatial hash is cleared and refilled with every enemy (cheaper than tracking moves when hundreds move every frame; cell arrays are reused so there is no garbage)." },
            { p = "5. Deferred calls queued during last frame run." },
            { p = "6. Player, spawner, enemies update, then beads, grabs, hazards, the director (events, encounters, mechanics, weather effects), bosses, the reward flow, the economy (shop restock) and the Final Swarm." },
            { p = "7. Solids push the player out of solid enemies." },
            { p = "8. The dead are removed, keeping the enemy array packed (swap with last), and returned to the pool." },
            { p = "9. Particles and weather update; landed particles become splats on the decal layer; corpses fade." },
            { p = "10. Hitstop check. If enough enemies died this frame (15 by default) and the cooldown allows, the world freezes for a beat and shakes. The run's biggest multi-kill can be saved as a picture." },
            { p = "11. Effects, floating texts, the decal fade, the stain budget (40 per second) and the combo timer tick. Rewards (frenzy, streaks, goals, routes) update last." },
            { p = "Nothing in a wave waits on anything but living enemies: events, hazards and gambles all end with the wave." },
        } },
        { title = "Coordinates and projection (src/core/iso.lua)", blocks = {
            { p = "The world is a flat square plane (x, y) plus a height z. All gameplay (movement, collisions, ranges, hitboxes) happens in world space; only drawing projects. The projection is 2:1 isometric:" },
            { p = "screen x = x - y\nscreen y = (x + y) / 2 - z\ndepth    = x + y          (drawn back to front by this)", color = "dim" },
            { p = "Iso.toWorld and Iso.screenDirToWorld turn the mouse and the right stick back into world directions for aiming." },
        } },
        { title = "Entities", blocks = {
            { p = "- Enemies (src/game/enemy.lua) are plain tables recycled through a pool, so spawning and killing hundreds a minute makes almost no garbage. An enemy carries its def (the content file), its behavior and per-instance state e.st, velocity, knockback velocity, flash/squash timers, status timers (stun, slow, poison, corrode, freeze), hidden (burrowed: untouchable, undrawn), alpha, heldBy (grabbed) and an optional elite affix." },
            { p = "- The player (src/game/player.lua) holds the character def, a stat block, the inventory, the attack / special / dash with their params (after skill tree mods), stamina, statuses (stun, blind, gum) and the 3D model pose." },
            { p = "- Props (src/game/props.lua) are neither: pebbles, twigs, acorns, cocoons, allies, the merchant, brood cells, reward blooms, map gambles. They never enter the enemy list, so they never hold a wave up." },
            { p = "- Hazards (src/game/hazards.lua) are what enemies leave or throw: ground zones (honey, acid, sand pits, with damage, slow, heal, pull and custom update / draw) and projectiles (acid spit, pebbles, curving shots with turn, onHitPlayer). Player attacks can swat projectiles back." },
            { p = "- The event bus (src/core/events.lua): each run owns one; enemy_died, player_hurt, wave_started, wave_cleared, item_taken, item_eaten, run_won, player_died, species_seen, nectar_changed... Items, achievements, records and the HUD listen without the emitter knowing about them." },
        } },
        { title = "Stats (src/game/stats.lua, src/config/stats.lua)", blocks = {
            { p = "A stat block holds base values plus modifiers from named sources (an item, a buff, a level-up card, a skill node, a keepsake). The final value is:" },
            { p = "final = (base + sum of adds) x (1 + sum of multipliers), clamped to the stat's min / max", color = "dim" },
            { p = "Some stats have a soft cap (Dodge: past 30% each point counts for less, never 60%). Fifteen stats exist (Max HP, HP Regen, Armor, Dodge, Speed, Damage, Attack Speed, Area, Knockback, Crit Chance, Crit Damage, Luck, Life Steal, Pickup Range, Dash Cooldown). Adding a stat to the config makes it usable by every item, card and bug, and its info(value) function explains the number in tooltips." },
        } },
        { title = "Combat (src/game/combat.lua)", blocks = {
            { p = "Attacks and procs never touch enemy health directly; they call Combat.damage(world, enemy, base, opts), so crits, knockback, procs, numbers and kills stay consistent. The order of a hit:" },
            { p = "1. Burrowed (hidden) enemies can't be hit; a grabbed prop only chips." },
            { p = "2. damage = base x (1 + Damage%) x coefficient." },
            { p = "3. Crit roll on Crit Chance; a crit multiplies by Crit Damage." },
            { p = "4. Shield ants (turtle ants) standing between the player and the target soak most of the hit." },
            { p = "5. Elite armour (Armored: 40% less), corrosion (vinegaroon acid: more), poison amp items, a queen behind her royal guard (30% of the hit)." },
            { p = "6. The behaviour's onHit(e, world, opts, dmg) may multiply it (counter-hits on charging ants, velvet ants ignoring hits under 8, hover wasps dodging)." },
            { p = "7. Damage is rounded (at least 1), logged to the run stats by source, and applied. Flash, squash, knockback (scaled by the Knockback stat and divided by mass), poison, slow, stun and corrosion from opts." },
            { p = "8. If it kills: the kill pipeline (nectar beads, splats, gibs, body knocked away, combo, frenzy, onKill procs, records)." },
            { p = "Procs may trigger procs, up to a depth that grows from 2 to 3 in late waves (Combat.MAX_PROC_DEPTH = 3 is the hard cap)." },
            { p = "Damage to the player goes through Player:hurt: dodge roll, then armour as 15 / (15 + armor) (negative armour increases damage), block / guard multipliers, at least 0.5 per hit. There are no invulnerability frames after a hit: only dashes, blocks, dodge and the frenzy move avoid damage. Raw environmental damage (events, stage hazards) skips player stats and procs (src/game/envfx.lua)." },
        } },
        { title = "Rendering", blocks = {
            { p = "The renderer is built so the draw-call count stays around 40 whether there are 250 or 1,500 enemies." },
            { p = "- One atlas (src/gfx/sprites.lua). Every sprite is a text grid (one character per pixel, a palette of letters, facing right). At load, each is rasterised and baked in 32 rotations into one texture, along with shadows, particles, health bars and glow blobs. LÖVE batches consecutive draws from one texture, so the whole horde is a handful of calls." },
            { p = "- 3D-looking bugs. Playable bugs have a model: a body sprite drawn as a stack of layers (darker and narrower at the bottom so it reads as a raised shell) over jointed legs drawn from a rig of hip, knee and foot points. Feet stay planted while the body moves over them, then lift and swing (tripod gait), kicking up dust. Centipedes and millipedes are kind = \"chain\" models: segments follow the head's path. The body bobs with each step, lunges over planted legs when attacking, recoils when hit and breathes when idle." },
            { p = "- Attack animations (src/gfx/anim.lua, clips in src/config/anims.lua): keyframed clips move the body (lunge, twist, rear, squash) and swing extra 3D limbs (scorpion tail, lobster claws, mantis scythes, stag jaws, spider fangs). Looked up as \"<bug>.<slot>\", then by the move's type, so a new bug reusing a move still animates." },
            { p = "- The floor (src/gfx/ground.lua) is pre-rendered once per stage into a canvas (one draw call): per-pixel concrete, lawn, grass blades, cracks, leaves, pebbles from the stage palette. Splats paint onto a persistent decal canvas that fades." },
            { p = "- Draw order (from World:draw): ground -> wet ground, horde tracks, decor -> hazard zones -> burrow mounds, landing shadows, nest holes -> route tunnels -> director ground layers (puddles, pits, lane warnings) -> beads -> swarm underlay (soft dark blobs that merge a crowd into one mass), elite auras -> shadows (one batch) -> props -> behaviour drawUnder (silk strands) -> move effects -> telegraphs (with Attack Warnings on) -> corpses -> threat outlines and rim light -> every actor depth-sorted (the enemy array is kept sorted in place by near-linear insertion sort) -> particles -> air layers (stage hazards, weather) -> lighting." },
            { p = "- Lighting. A light map is drawn (the player, effects, glowing particles, enemies with a light field, night lantern, warning lights) and multiplied over the scene from an ambient colour set by the time of day (src/game/daylight.lua). The Bold style adds a highlight roll-off; Glare Guard keeps additive effects from blowing out. A post shader (src/core/screen.lua) does brightness, colour filters, colour grade and heat haze." },
            { p = "- Particles (src/gfx/particles.lua) are pooled pixels with height and bounce, drawn from the atlas; glowing ones get a soft additive halo. Spawns scale down as the pool fills." },
            { p = "- Painted pictures (src/gfx/paint.lua): anything in the world that isn't an atlas sprite (props, map gambles, the antlion and its pit, the sparrow and anteater in src/gfx/beasts.lua) is painted once at runtime in Lua with lit blobs, strokes and a soft outline, then cached." },
            { p = "- UI draws at the window's resolution on top of the scaled world canvas, through src/ui/theme.lua." },
        } },
        { title = "Performance rules", blocks = {
            { p = "- Pool everything that is made per frame (enemies, particles, query results). No new tables per spawn: particle colours and options are module constants." },
            { p = "- Rebuild the spatial hash each frame rather than tracking moves." },
            { p = "- Cap what can pile up: stains per second, bodies in the air, glowing-particle lights, hitstop cooldown." },
            { p = "- When hundreds die at once only the first ~40 leave stains and remains." },
            { p = "- love . --profile --crowd --nojit --cpudraw benchmarks a fixed horde phone-like (no JIT); --gclines lists the lines that allocate the most. love . --selftest prints update / draw timings at 250 / 500 / 1,000 / 1,500 enemies." },
        } },
        { title = "Audio (src/core/audio.lua, src/core/music.lua)", blocks = {
            { p = "There are no sound files. Every effect is synthesised at start-up into SoundData, played through volume buses with voice limits (and positional panning, Audio.place)." },
            { p = "The music is one 8-bar loop in D minor rendered as six stems (pad, arp, bass, drums, lead, queen brass) that always play in sync. The game only changes each stem's volume, so the score follows the fight without ever skipping a beat: calm between waves, bass and drums in a wave, the lead when a big crowd is on you, toms and brass while a queen is out, a slowed fade when you fall. Each body plan (spiders and arachnids, beetles, crustaceans, myriapods, flyers, other insects) has its own band that swaps the arp, lead and drums for its own versions, and every bug has a riff generated from its id. Stems are cached as WAV files in the save folder; bump CACHE after changing the score. src/game/feedback.lua plays big-moment sounds (wave horn, clear chime, queen arrival, victory, defeat, low-health heartbeat); src/game/soundscape.lua adds ambient sounds and in-key stingers." },
        } },
        { title = "Input (src/core/input.lua, src/core/touch.lua)", blocks = {
            { p = "Game code asks about actions (\"was dash pressed?\"), never raw keys, so rebinding and controllers work everywhere. Input.lastDevice tells the UI which key caps or pad icons to show (Theme.glyph, Theme.rich turns (dash) in any text into the right key). On touch screens the controls appear by themselves: a floating stick on the left, Special (drag to aim), Dash, Attack, Frenzy, BAG and pause on the right; menus take taps and drags. Touch writes into the same Input (virtualDown, virtualMove, virtualAim, press), so game code needs nothing special." },
        } },
        { title = "Saving (love.filesystem save folder)", blocks = {
            { p = "File: Holds, Code", color = "accent" },
            { p = "settings.lua: every setting and key binding, src/core/settings.lua" },
            { p = "records.lua: lifetime stats, run history, achievements, amber, unlock progress, daily / weekly bests, src/game/records.lua, amber.lua, daily.lua" },
            { p = "prefs.lua: last bug and mode, favourites, sort, practice setup, artifacts on, keepsake, item pool, src/game/prefs.lua" },
            { p = "run.lua: a saved run to resume (bug, mode, map, act route, waves, bag layout, skills, economy, blessings...), src/game/runsave.lua" },
            { p = "cosmetics.lua: chosen location, map decor, skin per bug, src/game/cosmetics.lua" },
            { p = "tutorial.lua: which first-run hints were shown, src/game/tutorial.lua" },
            { p = "customwaves.lua: wave sets from the wave builder, src/game/customwaves.lua" },
            { p = "custom_bugs/<id>.lua: Bug Creator bugs (one script each), src/game/custombugs.lua" },
            { p = "music/: cached music stems, src/core/music.lua" },
            { p = "playtest_log.csv, highlights/: developer playtest log, highlight screenshots, src/game/playlog.lua, world.lua" },
            { p = "Saves are Lua tables written as text, so they can be read and fixed by hand. Test runs (--selftest, --profile, --balance) never write them." },
        } },
        { title = "Randomness and seeds", blocks = {
            { p = "A run has a seed (world.seed; Game.new( seed = n ) replays it). The species order, wave modifiers, the act route and the daily / weekly runs come from it, which is what makes run codes (swarmed1.<bug>.<map>.<mode>.d<danger>.<seed>.<artifacts>) and the daily run work. Everything uses love.math.random for this reason, even though it is slower on the interpreter." },
        } },
        { title = "Platforms", blocks = {
            { p = "- Desktop: LÖVE 11.4+ with LuaJIT. Discord status talks to the Discord app's local pipe through the FFI." },
            { p = "- Web: love.js, plain Lua 5.1. No goto, no LuaJIT-only libraries, no FFI (Discord switches itself off)." },
            { p = "- Phones: the web build, or swarmed.love opened in LÖVE for Android. Touch controls, left-handed layout, HUD and button sizes adapt." },
        } },
    } },
    { title = "Core gameplay systems", pages = {
        { title = "The player's bug", blocks = {
            { p = "A character file (content/characters/<id>.lua) gives a bug its name and texts, sprite and 3D model, stats (on top of the stat defaults), radius and scale, tags (lineage, item synergies, music band), a playstyle, and three moves:" },
            { p = "- attack (left mouse / J / RB, or automatic with Auto Attack on): fires on its cooldown at the aim. With Auto Attack it picks the nearest enemy." },
            { p = "- secondary, the special (right mouse / K / B): a stronger move on a longer cooldown. Some are held (silk walls, the mantis snatch), aimed by dragging, or charged." },
            { p = "- dash (Space / Shift / A): every bug's is its own: horn charges, flights, blocks, burrows, grapples, stamina modes." },
            { p = "Each move is ( type = \"<file in content/attacks or content/dashes>\", ...params ). The type file holds the code; the character holds the numbers. So the same move type can be tuned per bug, skill tree nodes can change params by name (attack = ( damage = ( mul = 0.12 ) )), and the Bug Creator can mix any move onto any body. The wiki volume lists every type and its params." },
            { p = "Aiming. Aim Mode = Mouse aims at the pointer (projected back into world space); the right stick always aims; otherwise moves aim where the bug faces or at the nearest enemy." },
            { p = "Stamina (src/game/stamina.lua). One pool per bug, shown as the green bar under health, shared by everything dash-like:" },
            { p = "- pressed dashes cost one charge (max / charges); notches on the bar mark charges;" },
            { p = "- hold modes (tiger beetle run, flights) burn stamina per second while Shift is held;" },
            { p = "- blocks (lobster, hermit crab, vinegaroon) cost a bit to raise, drain while held and per blocked hit, and break when the pool runs dry (locked out until Shift is let go)." },
            { p = "Refill starts a moment after the last spend; Dash Cooldown speeds it up. Dash tech (src/game/dashtech.lua): a kill during a pressed dash refunds half its cost, and dashing again within 0.45 s of the last one ending is 15% faster per link, up to three." },
            { p = "Statuses on the player. stun (can't act), blind (vision shrinks; bald-faced hornets), gum (mason bee mud, nasute glue), slows from honey and resin, poison, latched driver ants (dash to shake them off), held by a tarantula hawk (mash to struggle). The hissing roach is immune to debuffs." },
            { p = "Bug rules (src/config/bugrules.lua, src/game/bugrules.lua): a few bugs bend how items work for them, through hooks on the inventory's triggers (onEat, procChance, procRepeats, stats, start). Dung Beetle grows from eaten items, Hermit Crab gets an extra bag row but slows per filled cell, Orb Weaver's procs fire twice on webbed ants, Hissing Roach heals double from eating, Scorpion's poison items proc more." },
        } },
        { title = "Enemies and their AI", blocks = {
            { p = "An enemy file gives stats (hp, speed, damage, radius, mass, xp, biteRate), a family, a sprite, spawn rules (minWave, weight, groupSize), a behavior id with behaviorParams, colours for gibs and splats, tags, and text (description, lore, tip). Flags add mechanics: solid, shield (soaks hits for ants behind it), venom, light, onDeath, noElites, noStun, boss." },
            { p = "Behaviours (content/behaviors/*.lua) are the AI. update(e, world, dt, params) sets the desired velocity e.mx, e.my; the world integrates movement, separation and knockback. Optional hooks: init, onHit (react to a hit; returns a damage multiplier), draw (telegraphs, shown with Attack Warnings on) and drawUnder (things in the world, always drawn). Shared helpers in src/game/ai.lua: AI.toPlayer, AI.goTo, jumps (startJump / updateJump), AI.hover, AI.sting, AI.group (whole-swarm coordination, e.g. warrior wasps all diving at once), AI.nearestOther." },
            { p = "The swarm look. Ants spawned together by a stream are linked into a follow-the-leader column (content/behaviors/column.lua): each ant walks to where the one ahead was a moment ago, so columns snake in from the edge. Within engage range the column breaks into a ring that orbits and tightens around you. Ants pack tightly (personalSpace), walk with a stop-and-go gait, and share a dark swarm underlay (swarmShade) so a horde reads as one flowing mass." },
            { p = "Bites. Every ant touching you bites on its own biteRate timer, and there are no invulnerability frames, so damage scales with the crowd. The HUD warns \"SWARMED xN\" and the screen edges turn red." },
            { p = "Fighting back. Hitting an ant while it winds up or charges (bullet, soldier, big-headed, bulldog, desert, trap-jaw, Dracula ants) staggers it out of the attack, and a hit during its dash is a counter for +50% damage. Attacks swat acid globs and pebbles back at the ants, faster." },
            { p = "Engine hooks the behaviours use. e.hidden (burrowed: no damage, targeting, bites or drawing), e.alpha (near-invisible cuckoo bees), e.heldBy (carried by another enemy or grabbed by you), player:stun / blind / gum, hazard zones with damage, pull, update and draw, curving projectiles, world.recentDeaths (react to kills nearby)." },
            { p = "Elites (content/elites, src/game/elites.lua). From wave 2 any ant can roll an affix (Aggressive, Gilded, Armored, Venomous, Volatile, Zombified via jewel wasps): health / damage / speed / mass / scale multipliers, tint and glow, a coloured ground aura, a safeColor for the colourblind palette, and effects (armour, venom, bonus XP, death bursts). A species can give an affix its own twist (elites = ( aggressive = ( params = (...) ) )). Gilded elites add a card to the next item choice." },
            { p = "Queens (behavior = \"queen\"): one per species, keep their distance and lay broods of their own kind until they die. Every queen arrives ringed by a royal guard (armored brood); she takes 30% damage until the guard is dead. At half health she enrages (faster, a brood rushes in). The last crowned queen of the final wave is the Empress, with two phases. On the middle wave of each act (3, 8, 13) the first elite is a named champion (\"Cinder, Worker Ant\": 3x health, the boss bar, 40 XP and 12 nectar)." },
        } },
        { title = "Grabs, throws and props", blocks = {
            { p = "src/game/grab.lua holds and throws ants for grab moves (stag beetle, mantis, jumping spider, dragonfly, emperor scorpion, vinegaroon, rhino horn, whip scorpion). A held ant stops thinking; whoever holds it sets its position. A thrown ant flies along an arc, bowling over every ant it passes, and crashes down. Grab.collect lets the same moves pick up props: pebbles, twigs and acorns pop off the ground when hit, bounce, squash, chip, spin when struck off-centre, scatter in blasts, knock into each other like marbles, and flatten every ant they roll over while fast (src/game/props.lua)." },
        } },
        { title = "Items and the bag", blocks = {
            { p = "src/game/inventory.lua. The bag is a 10x3 grid (one more row every 15 waves survived) of shaped items: bars, L's, T's, S's, crosses, blocks, defined by shape rows or a size rectangle, turnable in quarter turns. There is nothing to equip: everything in the bag counts, copies stack, and the only limit is fitting shapes in, so bigger items are stronger for the room they take." },
            { p = "An item file has name, description / effect text, rarity, category, tags, price, stats (flat adds) and statsMult (multipliers), and procs:" },
            { p = "procs = ( ( trigger = \"onKill\", chance = 0.1, cooldown = 1,\n            effect = function(ctx, stacks, state) ... end ) )", color = "dim" },
            { p = "Triggers: onHit, onKill, onHurt, onDash, onDodge, onBlock, onAttack, onSpecial, onWaveStart, onEat (can raise the HP a meal heals) and onTick (every frame). Any system can fire a new trigger name with inventory:trigger(name, ctx); the bug rule, the skill tree and level-up perks see every trigger too. src/game/itemfx.lua has helpers for timed effects: every-N-seconds timers, timed buffs, poison patches, trails, orbiting critters, guards and per-item state." },
            { p = "Chances never reach 100%. Luck, the proc snowball and extra copies stack hyperbolically (Inventory.stackChance). A proc whose effect doesn't grow with copies can set chanceStack to fire more often per copy instead. Proc snowball: every wave raises all proc chances (+7% a wave, up to x2.2) and from wave 8 procs can set off one more link of procs." },
            { p = "Eating an item removes it and heals by rarity (common 8, uncommon 14, rare 22, legendary 35, molted 50 HP; +25% per extra cell). Cursed items can't be eaten, only scrapped." },
            { p = "Rarities (src/config/rarities.lua): common, uncommon (from wave 1), rare (wave 3), legendary (wave 6), cursed (wave 3, purple: a big upside with a real cost), molted (never dealt). Categories (src/config/categories.lua) answer \"what is it for\": Attack, Elemental, Guard, Mend, Move, Control, Fortune, Cursed. The bag sorts by category, fills each item with its category colour and outlines it in its rarity colour." },
            { p = "Item icons are not hand-drawn: tools/make_item_icons.py models each item from lit 3D shapes with real materials (gloss, grain, translucency), lit by a warm low sun and cool dusk ambient, at 28 px per cell, then reduces it to a small palette." },
        } },
        { title = "Parasites (src/game/parasites.lua, numbers in src/config/parasites.lua)", blocks = {
            { p = "Ten items of rarity parasite (parasite = true in content/items) live in your bug instead of the bag: Flu halves your health and doubles your damage, Cordyceps Puppeteer walks for you, Head Lice breed every wave... Each is a big change to how you play with a real cost." },
            { p = "- They take no bag space and never touch the grid, so nothing can eat, scrap, sell, sort, molt or clone them, but they count like bag items for stats, procs and the HUD item row (Inventory:recount adds them in)." },
            { p = "- One copy each, a few different ones at most." },
            { p = "- Void-style feeding: a parasite can say feeds = ( ids, stats ). When it gets in, every copy of those items in the bag is devoured and each adds stats for good." },
            { p = "- Optional steer(player, wx, wy, mag, dt, item) bends your walking; item.level is a number a parasite grows (lice, botfly larva), saved with the run." },
            { p = "- The only cure is a Green Mushroom (content/props/green_mushroom.lua): a rare sprout that shows up while you carry one. Walking into it purges every parasite at once." },
            { p = "- A mode or Custom Waves set can turn parasites off with the parasites run rule." },
        } },
        { title = "Molting and set bonuses (src/game/molting.lua)", blocks = {
            { p = "Both are about which items touch in the bag (share a cell side)." },
            { p = "- Molting (content/molts): when every piece of a recipe touches as one group, the group molts into the recipe's item after the next queen wave is cleared (Ember Gland + Bombardier Gland -> Magma Gland). Seams between pieces glow teal; a line over the bag says what will molt. Records > Recipes is the recipe book." },
            { p = "- Tag sets: three items sharing a tag, all touching in one group, give the tag's set bonus (Warpath +8% Damage, Bulwark +5 Armor...); five give it twice. The bag draws the group's seams in the tag colour." },
        } },
        { title = "Level-ups and skill points", blocks = {
            { p = "src/game/levelups.lua, src/game/skills.lua. Kills give XP (World:grantXP). The curve is fast: the first level is about ten kills and a 15-wave run reaches about level 35. Each level plays a chime, half a second of slow motion and a ring of light, and opens three cards right there, mid-wave (setting: or at the wave's reward bloom)." },
            { p = "Cards come from content/levelcards in five families: stat (small boosts), pact (big boost with a cost), growth (grows every wave), perk (a lasting proc effect that ranks up) and instant (happens now). Each card rolls a rarity that multiplies its numbers: common x1, uncommon x1.33, rare x1.66, legendary x2; Luck tilts the odds." },
            { p = "Skipping a pick banks one skill point, the only way to earn them. So every level is a choice between a boost now and a step down the tree. Other systems grant picks with LevelUps.grant(world, n, ( source, minRarity, now )) (brood cells, routes)." },
            { p = "Skill trees (content/skilltrees/<bug>.lua): four branches. Three are the bug's own (attack, special, dash/body), each with five tiers: a 3-rank stat node, an upgrade, an either/or fork, a stronger upgrade, and a capstone that changes how the move plays (echoes, fans of copies, every-Nth empowered strikes, thrown ants that explode, procs). The fourth is a kin branch shared by the bug's lineage (content/skillbranches: Beetle, Spider, Arachnid, Tidepool, Myriapod, Insect Kin), topped by the tree's own signature node. Nodes are plain data: attack = ( damage = ( mul = 0.12 ) ), echo = ( move, delay, mult ), empower = ( every, mods, text ), procs = (...), stats = (...). A whole tree costs about 45 points, more than a run can earn, so every run builds differently." },
        } },
        { title = "Combat feel and rewards (src/game/rewards.lua, numbers in src/config/rewards.lua)", blocks = {
            { p = "- Frenzy meter: kills fill it (elites and queens more). Full, it unleashes the bug's super move from content/frenzies (Quake: a shockwave across the screen; Thunderstorm for flyers). You can't be hurt while it runs, the game slows for a moment, and a short buff follows." },
            { p = "- Kill streaks: every 50 kills in one combo (the combo breaks after 2.5 s without a kill) gives a random short buff from content/streaks; Carnage needs 150." },
            { p = "- Hitstop and slow motion are rare on purpose: the multi-kill hitstop needs 15 kills in one frame and then waits 4 s; slow motion needs 30 and waits 10 s. Heavy hits use World:hitStop(t), which respects the Hit Stop setting." },
            { p = "- Deaths: a hit sprays hemolymph along the blow, leaves a wet pool, flings body bits that land and stay, and knocks the body away to darken and fade on the decal layer." },
            { p = "- Nectar beads: every kill spills beads worth the ant's XP; inside Pickup Range they drift in faster and faster; close beads merge into bigger ones so a massacre stays readable. At a wave clear every bead flies to you with a chime that climbs note by note." },
            { p = "- Ground pickups (content/pickups): Nectar Magnet (pull the whole floor), Royal Jelly (frenzy full), Frost Dew (the swarm freezes for 2 s; rare, from wave 4, never again for 60 s)." },
        } },
    } },
    { title = "Runs, waves and the arena", pages = {
        { title = "Run structure", blocks = {
            { p = "A standard run (Colony mode) is 15 waves in three acts of five, each act on its own map (src/game/acts.lua). Act 1 is the map you picked; acts 2 and 3 are other maps you own, planned from the run's seed. After the queen of waves 5 and 10, her rewards and the shop, starting the next wave carries the whole run to the next map (through a run save, as if resumed) with an \"Act 2 of 3\" card and a breather." },
            { p = "- Every 5th wave is a queen wave. Clearing it heals fully, molts touching items, and pays a royal brood cell." },
            { p = "- Wave 15 is the final boss wave: crowned queens (2 by default, at 1.6x health) one after another, then the Empress with two phases. Clearing it wins the run." },
            { p = "- After a win the player can Keep Going (the bag grows a row, waves keep getting harder, every 15th wave is another final wave) or take on the Final Swarm: 60 seconds of every species met pouring in from every side with lots of elites and a crowned queen halfway (src/game/finalswarm.lua)." },
            { p = "- A run ends when the bug falls, when the player ends it at victory, or with Abandon Run. Every real run pays amber for the Burrow." },
            { p = "Acts are off in practice, the daily run, endless, custom or scripted waves, modes with acts = false, before a player's second run, and in modes whose travelActs run rule is off." },
        } },
        { title = "The wave director (src/game/spawner.lua)", blocks = {
            { p = "Waves teach the colony one species at a time. Wave 1 is plain workers; each later wave introduces exactly one new species, which walks in first and alone under a \"NEW SPECIES\" card with its description and tip, before the rest of the wave mixes it with species already met. Every fifth wave a queen of a species you've met comes instead." },
            { p = "- Introduction order: by spawn.minWave, then the most common first, then shuffled a little per run (minWave x 0.6 plus a random spread, workers always first) so bees, wasps and termites can turn up early. A map's fauna favours some species (they come sooner and more often) and can name the one that opens wave 1. A mode's families, enemies and exclude restrict who comes." },
            { p = "- Groups and entries: each wave sends groups (3, +1 a wave) groups of 14 to 22 ants, growing 15% a wave, from 2 entry points in wave 1 up to 6, with pincer pairs from opposite sides later. Stray packs trickle in from other edges while the wave runs. Up to 900 alive at once." },
            { p = "- Ways in (src/game/entries.lua): most groups march from the edge, but some burrow up near you (the soil heaves first), flyers drop from the sky (a shadow grows where they land), nest holes open in the floor and pour out the wave's groups (hit a hole three times or dash over it to seal it), and burrow rings surround you. Every way is telegraphed and never opens on the player." },
            { p = "- Healing: clearing a wave heals 20% of max HP; a queen wave heals fully." },
            { p = "- Scripted waves: a mode with a waves list (Gauntlet, Custom Waves) sends exactly what each wave names instead." },
            { h = "Pacing (src/game/pacing.lua)" },
            { p = "Piece: What it does", color = "accent" },
            { p = "Big early waves: Waves 1-3 send 2.2x / 1.8x / 1.4x the ants at 45% / 60% / 80% health: lots to mow down from the first second." },
            { p = "Wave modifiers: From wave 3 (55% chance, sometimes two from wave 9), never on queen or final waves: Swarm, Armored, Frenzied, Elite Pack, Ambush (half the wave bursts up in a ring around you), Shield Wall (ranks step out at once), Pincer, Undermined. Rolled ahead from the seed so the HUD can preview them." },
            { p = "Overlapping waves: When a normal wave is down to its last 15%, you pick your item and the next wave marches in while the stragglers are still about." },
            { p = "Straggler call: With 5 or fewer ants left, any far away burrow up near you. The last 6 also rush 1.5x faster." },
            { p = "Par time and heat: Each wave has a par time from its size. Under par pays bonus XP; past it the ants speed up and hit harder (up to +35% / +25% after 40 s)." },
            { p = "Live pressure: While you stay healthy and untouched, packs come quicker and bigger and ants a little faster; taking damage eases it off." },
            { p = "Early call: Starting a wave before its countdown ends, or sending a wave's rest in with Next Wave, pays bonus XP, more for each wave in a row." },
            { p = "Royal guard: Every queen arrives ringed by armored brood; she takes 30% damage until they are dead (\"BREAK THE ROYAL GUARD\")." },
            { p = "Tuning lives in the Spawner DEFAULTS; a stage's spawn and a mode's spawn override any of it, and any piece can be set to false." },
        } },
        { title = "The arena director (src/game/director.lua)", blocks = {
            { p = "Everything in a wave besides the ants walking in. It never holds a wave up: a wave ends only when every enemy is dead, and events still going end with it." },
            { p = "- Mid-wave events (content/events, run rule Often / Normal / Off): from wave 2, 0-2 per wave, 6-24 s in. Honeydew rain (sweet puddles: ants stop to feed, you heal), an anteater's tongue licking down a red lane, a boot stomp (a shadow that follows you, then flattens everything), a flood (wading, a current, small ants drown), colony war (a red rival colony fights yours), rolling dew drops, falling acorns (they stay as things to roll), a lawnmower lane, web cocoons (break one to free a bug that fights beside you for 20 s), the merchant beetle (sells items for nectar) and the aphid matriarch (clones an item). A map's events = ( id = weight ) and a mode's eventWeights / events = false change the odds." },
            { p = "- Stage hazards (content/bosses, hazard = true): the antlion pit, the sparrow and the giant anteater. They have no HP and nothing to hit or grab. From wave 6 each wave may roll one (7% more chance per wave, up to 50%, at least 2 waves apart, never on a queen wave or the final wave), arriving 6-20 s in. They never share a wave with events, hunt for about 25 s at most, and everything they do kills ants and hurts you alike. Lead the swarm into them. They leave with bonus XP. The antlion digs a pit that drags ants and you to its jaws and flicks sand, then tunnels off and digs again near you." },
            { p = "- Stage mechanics (content/mechanics): Puddled Patio's rising puddle, Overgrown Lawn's long grass closing in, Dappled Garden's drifting sun patches (speed everyone up; shade slows ants)." },
            { p = "- Weather (content/weather, src/game/weather.lua): passing spells of rain, fog, wind, pollen, storms, heatwave. Wind pushes everyone downwind (lighter bugs more), rain slows the fight (ants most), heat speeds it up. A banner says what changed." },
            { p = "- Map gambles (src/game/gambles.lua): from wave 2 a risky spot may pop up: a dewdrop shrine (stand in its ring while it fills and calls ants in; then walk into one of three permanent blessings), a challenge bell (ring it, kill the tough pack it calls in time for a rare reward), a gamble flower (spin for nectar: items, blessings, nectar x3, XP, a heal... or nothing, ants, or a small permanent curse)." },
            { p = "Everything that changes movement goes through world.env (player / enemy speed, drift, the player's inset from the walls, a per-spot speed field). Raw environmental damage and the shared warning-lane drawing are in src/game/envfx.lua." },
        } },
        { title = "Side tasks in a wave", blocks = {
            { p = "- Mini-goals (content/goals, from wave 2): stop the courier ant before it crosses, guard the aphid, reach a combo, get a burst of KOs. Success pays XP and frenzy; failing costs nothing." },
            { p = "- Treasure ant (from wave 3): a gilded ant pops out and runs. Catch it within 14 s for a pile of XP, half a frenzy meter and a brood cell; otherwise it burrows away." },
            { p = "- Route gates (content/routes, src/game/routes.lua): after a wave two tunnels open beside you. Walk into the safe one (fewer ants, no elites) or the hard one (more ants, more elites or tougher ants; pays XP, frenzy or a rarer item card). Ignore both for a normal wave." },
            { p = "- Brood cells: a slain queen drops a royal brood cell, a caught treasure ant a plain one. Walking in (or clearing the wave) rolls 1, 3 or 5 level-up cards with a fanfare (queen odds 50/38/12, treasure 74/22/4)." },
        } },
        { title = "Wave rewards (src/game/rewardflow.lua)", blocks = {
            { p = "A cleared wave's rewards are a moment in the arena, not a pile of screens:" },
            { p = "1. Every bead flies to you. A glowing reward bloom sprouts next to your bug, labelled with what is inside. Walk into it (or press Next Wave, or wait 5 s and it rolls to you)." },
            { p = "2. It bursts and the item choice opens: pick 1 of 3 items. A boss wave guarantees rare or better; each gilded elite killed adds a card. With Level-Up Cards: At Wave End, a steps strip shows the level-ups first." },
            { p = "3. What you took flies out of the bloom into your bug, and a gain card on the left says what you got." },
            { p = "Item choice helpers (src/game/choices.lua): REROLL redraws every unlocked card (3 per run, +1 per queen), LOCK keeps a card for the next choice, BAN removes an item from the run (2 per run). Cards show tags (lit when the bag shares them) and a stat preview (\"Speed 120 >> 138\"). From wave 4, 15% of choices deal a Sealed Cocoon: rare or better, but hidden until taken. If the pick doesn't fit, the bag opens holding it." },
        } },
        { title = "Nectar economy (src/game/economy.lua, numbers in src/config/shop.lua)", blocks = {
            { p = "Nectar is the run's only currency." },
            { p = "- Shop: the SHOP tab of the inventory window, open the whole run (the game pauses). 3 items and 1 stat boost; two presses to buy. Restocks every minute of play (faster with shopSpeed items, never under 15 s). LOCK keeps an offer; REROLL costs nectar and gets dearer until the restock. Prices rise every wave (base: common 60, uncommon 100, rare 170, legendary 300, cursed 90)." },
            { p = "- Interest: the moment a wave is cleared, banked nectar earns 10% (capped; the cap grows each wave)." },
            { p = "- Scrapper: SCRAP in the bag turns an item into 40% of its price in nectar; rare or better also gives back a reroll." },
            { p = "- Merchant beetle: an event that sells for nectar a fifth under shop price." },
        } },
        { title = "Run rules (src/game/rules.lua)", blocks = {
            { p = "Switches that change how the game itself plays (spawns, difficulty, pacing, events, gambles) are not settings. The main game always plays with the defaults, so everyone plays the same game; Settings keeps comfort options only (auto attack, aim, health bars, hit stop...). Only a run's mode changes them: a Custom Waves set's rules table (picked in the wave builder) or a mode file's rules = ( key = value )." },
            { p = "Rules.get(key) reads the value for the current run, Rules.begin(tbl) starts a run with its mode's rules, Rules.set(key, v) is a developer / selftest override. Rules offered in the wave builder: Map Gambles (often / normal / off), Parasites, Level-Ups (cards or skill points), Overlapping Waves, Wave Heat, Mini-Goals, Route Gates, Weather Effects and Dash Tech. Main-game-only rules: mid-wave events, boss encounters, wave modifiers, species order, elite frequency, difficulty and travel acts." },
        } },
        { title = "Game modes (content/modes)", blocks = {
            { p = "Mode: Shape", color = "accent" },
            { p = "Larvae: Beginner: smaller, weaker waves, long breaks, a new species every other wave, no elites." },
            { p = "Colony: Standard: every family, 15 waves, queen every 5th." },
            { p = "Swarm: Hard: more columns from more sides, tougher ants, short breaks, elites twice as often." },
            { p = "Anthill / Hive / Mound: Ants only / bees, wasps and hornets only (boss pool instead of queens) / termites only." },
            { p = "Champions: Small groups, every enemy is an elite." },
            { p = "Endless: Pick starting items on a point budget; no waves and no breaks; the level climbs every 40 s." },
            { p = "Gauntlet: Ten hand-made scripted waves, the same every run." },
            { p = "Royal Court: Boss rush: a queen every wave for ten waves." },
            { p = "Blitz: Eight huge waves with no breaks, two new species a wave, faster level-ups." },
            { p = "Mayhem: Wave modifiers on every wave, extra events, a boss or hazard every third wave." },
            { p = "Custom Waves: The wave builder: sets of hand-made waves (groups, queen, modifiers, events, encounter), shareable as a Lua table on the clipboard (pasted text runs with no globals and a step limit, so it can only be data)." },
            { p = "Tutorial: Hidden: 14 guided lessons (src/game/lessons.lua)." },
            { p = "Plus the Daily Run (today's date seeds the bug, map, species order and every modifier), the Weekly Challenge (a new seed every Monday picks the bug, map and two artifacts), Practice (pick a bug, mode, wave and species; never recorded) and Run Codes (copy a finished run's code, play the same run on another machine)." },
            { p = "A mode can override any stage wave setting (spawn), restrict enemies, scale enemy health and damage (enemyHp, enemyDamage, hpPerWave), change elite odds, set finalWave (false = never ends), and override the reward, shop, nectar, item choice and level-up numbers (rewards, shop, nectar, itemChoice, levelUps), or switch systems off (encounters, events, gambles, onramp, acts)." },
        } },
        { title = "Run saves (src/game/runsave.lua)", blocks = {
            { p = "A run saves itself at every wave clear, on Pause > Save & Quit, and when the window closes. The save is a snapshot of what makes it your run: bug, mode, map, act route, waves cleared, time, KOs, HP, the bag (every item where you put it and how it's turned), skills, level-ups, economy, blessings and curses, artifacts and keepsake. A run saved mid-wave plays that wave again. Abandon, defeat and End Run delete it. Act travel uses the same save to carry the run to the next map." },
        } },
    } },
    { title = "Between runs: progression, menus and the Bug Creator", pages = {
        { title = "Teaching the game", blocks = {
            { p = "- Gentle Start (src/game/onramp.lua, numbers and card text in src/config/onramp.lua). A new player meets the systems a piece at a time. First run: no elites before wave 4, treasure ant and the nectar shop from wave 3. Mini-goals, wave twists, garden events and map gambles join in run 2; route tunnels and big visitors in run 3; until run 4 a wave has at most one event and never one beside a visitor; act travel from run 2. The first time each system shows up, a short \"NEW\" card explains it, and from then on it is never held back again. Saves with 6+ runs count as having met everything. Systems ask OnRamp.allows(world, id, wave) before they appear." },
            { p = "- Tutorial (main menu until finished once): a guided fight in a hidden mode run by src/game/lessons.lua. The colony's own waves are off; 14 lessons each bring in what they need (move, attack, dash, special, the swarm, nectar, a level-up, an item choice, the bag, the shop, frenzy, an elite, a queen). Nobody can fall in it and it isn't recorded." },
            { p = "- First-run hints (src/game/tutorial.lua): move, attack, dash, special, swarmed, items, skill points, queens; each once." },
            { p = "- Field Guide (main menu and pause): one short page per system (src/config/guide.lua), a set-bonus page from the tag config, and the bug and item catalogues. Pages for systems Gentle Start hasn't shown yet read \"? ? ?\"." },
            { p = "- New species cards and first sightings: the wave that introduces a species names it with its description and tip; anything else seen for the first time (broods, escorts, hatchlings) gets a smaller card on the left." },
        } },
        { title = "Meta progression", blocks = {
            { p = "The rule: between-run progress buys new things to find, never raw power." },
            { p = "- Amber (src/game/amber.lua, src/config/amber.lua): the currency kept between runs. Every real run pays some when it ends, won or lost: 2 a wave cleared, 4 a queen, 1 per 10 elites, 1 per 200 KOs, 20 for a win (custom waves pay half). Veterans get a one-time head start." },
            { p = "- The Burrow (src/states/burrow.lua): shelves of item packs (their items stay out of every choice and the shop until bought), maps, modes, artifacts and keepsakes. Press once to look, twice to buy, with a fanfare. API: Amber.owns / itemOpen / stageOpen / modeOpen / buy / next." },
            { p = "- Artifacts (content/artifacts, src/game/artifacts.lua): Risk of Rain 2-style run rules, bought once, switched on or off in mode select. They can change the game params before the world is made (Metamorphosis picks the bug) and the world after (world.danger multipliers, stat mods, the frenzy meter). Glass Carapace, Teeming, Giants, Royal Guard, Twin Queens, Heatwave, Mixed Colony, Frenzy Tide, Metamorphosis." },
            { p = "- Keepsakes (src/config/keepsakes.lua): one small trade a bug carries into a run, never a straight gain (Snail Shell: more health, slower; Wasp Sting: more damage, less health...)." },
            { p = "- Unlocks (src/config/unlocks.lua): eight bugs open from the start; each other bug opens through an in-run goal (\"Clear wave 5 as the Rhino Beetle\", \"Kill 25 ants mid-dash in one run\"). Some items are locked the same way. Goals are achievements in the Unlocks category, so progress shows in Records and an \"Unlocked\" card pops mid-run. Unlock Everything (Settings > Gameplay) opens bugs, items, danger levels and skins; locked things show hints." },
            { p = "- Danger levels (src/config/danger.lua): per bug, Danger 0-5, each adding one rule (more elites, less healing, faster ants, tougher ants, bigger groups and an extra crowned queen). Winning at a level opens the next; the highest won shows as mastery stars." },
            { p = "- Item Pool: no longer a setting. The main game always offers every unlocked item; a Custom Waves set can switch items out of its own choices (itemsOff, at least 12 stay in)." },
            { p = "- Records and achievements (src/game/records.lua, content/achievements): lifetime totals, a page per bug, the last 50 runs with their bags, kills per species and family, 123 achievements (a value(profile, run) and a goal, checked twice a second). Several files generate entries from other content, so new bugs and modes get achievements automatically. Some unlock cosmetics." },
            { p = "- Cosmetics (src/game/cosmetics.lua): the starting location, map decor (content/decor) and a skin per bug (content/skins: hue, saturation, brightness, tint, light)." },
        } },
        { title = "Run summary and accessibility", blocks = {
            { p = "- Run summary (results, victory and pause): damage by source (items, attacks, specials, dashes, thrown ants, poison, all attributed by src/game/runstats.lua), kills by species, a dealt / taken graph per wave, the closest achievements and the run's seed." },
            { p = "- Death recap: what killed you and your last 5 hits taken." },
            { p = "- HUD Detail Full or Clean; HUD Size (default 75%); enemies-left counter and wave progress; next-wave preview; off-screen markers for queens and elites; combined damage numbers; enemy health bars (off / elites & queens / when damaged / always)." },
            { p = "- Colourblind-Safe Colours: elites use Okabe-Ito safeColors; ground hazards are coloured by what they do (harmful orange, slowing blue, healing yellow). High-Contrast Warnings: mounds, nest holes, shadows, landing rings and wind-ups get dark outlines and thicker rings (src/ui/palette.lua)." },
            { p = "- Visibility (Lighting tab): background dim, actors pop, see-through silhouettes, threat outlines, horde depth, danger compass, clear space, low-health pulse, Glare Guard. Hold To Inspect (V / Left Alt) slows the run and labels the enemies near the pointer." },
            { p = "- Comfort: Game Speed, screen shake, hitstop and slow-motion switches, flashing limits, Photo Mode, pause on focus loss or controller unplug." },
        } },
        { title = "The screens", blocks = {
            { p = "Screen: File, Notes", color = "accent" },
            { p = "Title: src/states/menu.lua, Live demo fight behind it. Resume, Play Again, Play, Burrow, Bug Creator, Field Guide, Records, Cosmetics, Settings." },
            { p = "Mode select: src/states/modeselect.lua, Map row, keepsake, artifacts; modes grouped (Your run / Modes / Challenges / More); daily, weekly, run codes, practice, custom waves." },
            { p = "Bug select: src/states/charselect.lua, Portrait grid grouped by family with family tabs, favourites, sort and playstyle filter, danger picker, live move preview." },
            { p = "Arena: src/states/game.lua + src/ui/hud.lua, src/ui/runhud.lua, The run." },
            { p = "Inventory window: src/states/bagtabs.lua, BAG (inventory.lua), SKILLS (skilltree.lua), SHOP (shop.lua). Pauses the run." },
            { p = "Level-up, item choice, brood cell, cloning: levelup.lua, itemchoice.lua, broodcell.lua, duplicate.lua, Overlays." },
            { p = "Pause: src/states/pause.lua, Every stat (hover for meaning) and every bag item's full effect; Photo Mode, Field Guide, Save & Quit." },
            { p = "Results: gameover.lua, victory.lua, runsummary.lua, Amber paid, run code, keep going, Final Swarm." },
            { p = "Settings: src/states/settings.lua, Generated from the schema; tab presets; live preview beside Video / Lighting / Camera." },
            { p = "Burrow, Records, Cosmetics, Field Guide, Practice, Item Pool, Artifacts, Loadout, Wave builder: src/states/*.lua" },
            { p = "Bug Creator: creator.lua, bugmixer.lua, codeeditor.lua, painter.lua, blockeditor.lua, rating.lua, Below." },
        } },
        { title = "The Bug Creator", blocks = {
            { p = "Main menu > Bug Creator makes new playable bugs. A custom bug is an ordinary character definition with custom = true, registered in Content.characters, so bug select, records and runs need nothing special. Each is one Lua script in the save folder (custom_bugs/<id>.lua; ids always start with custom_, so a custom bug can never replace a built-in one). The full field-by-field reference is docs/CUSTOM_BUGS.md, reproduced at the end of the Reference volume." },
            { p = "- Mix Parts (bugmixer.lua): one bug's body, another's attack, special and dash, plus size, colours, stats, an item rule and a skill tree, with a live preview. Build from blocks makes a move with no code: a list of blocks (lunge, wait, swing, slam, thrust, shockwave, sweep, shoot, lob, puddle, push, pull, wall, heal, shield, speed, vanish, afflict, ring, shake, hitstop, sound...), and more steps make a combo. The mixer also sets the ultimate, hit look and sounds, a status effect, pets, a molt and the title card." },
            { p = "- Write a Script (codeeditor.lua): a small sandboxed Lua script. Moves can be written in code against the me toolkit (src/game/scriptmoves.lua: me.hitArc, me.hitLine, me.hitCircle, me.lunge, me.after, me.state, me.hit hitboxes with wind-up, sweep and feel...): press, hold-to-charge, hold, and stamina-mode moves, code on game events, own animations, sounds and skill tree." },
            { p = "- Paint a Bug (painter.lua): a pixel grid with pen, fill, picker and mirror, a body-part kit (7 heads, 6 middles, 6 backs), draggable leg joints, add-on limbs (claws, blades, tails, horns, feelers, wings)." },
            { p = "- Template Gallery (content/bugtemplates): ten ready bugs (tank, summoner, sniper, trickster, berserker, bomber, vampire, shapeshifter, pet master, glass cannon). Examples: Stick Insect, Velvet Worm." },
            { p = "- Test Arena (training dummies, hitboxes, DPS meter), Rate It (src/game/bugrating.lua: the bug plays the same short fight as three built-in bugs; 100 = as strong as them), challenges, share codes (SWARMED-BUG:... on one line)." },
            { p = "- Safety: scripts run in a sandbox (no files, love, require, load, os, io, debug or metatables), with an instruction budget (about a million steps to build, a budget per call after) and 32 MB; bytecode is refused; every number that comes out is clamped (damage <= 500, cooldowns >= 0.03 s, counts <= 40)." },
        } },
        { title = "Game icon and Discord status", blocks = {
            { p = "- Icon (assets/icon/): a bombardier beetle ringed by worker ants, painted with the game's own models by love . --makeicon (src/debug/iconmaker.lua). conf.lua uses icon_256.png for the window; the web build uses it for the tab and phone home screen; swarmed.ico / swarmed.icns are for shortcuts and packaged builds (tools/make_icons.py)." },
            { p = "- Discord \"now playing\" (src/core/discord.lua, src/game/presence.lua): talks to the Discord desktop app's local pipe directly through LuaJIT's FFI, with no DLLs. About once a second it looks at the screen stack and builds a status (bug, wave, mode, danger, run time; menus, the Bug Creator and the sandbox get their own lines). It switches itself off on the web, on phones, in tests, when Discord isn't running, or with Settings > Interface > Discord Status off. It needs the Application ID of a \"Swarmed\" app from the Discord Developer Portal in src/config/discord.lua (or SWARMED_DISCORD_APP_ID). Test without Discord: python3 tools/fake_discord.py." },
        } },
    } },
    { title = "Tools, tests and how to add things", pages = {
        { title = "Developer mode", blocks = {
            { p = "On by default while the game is being built (Settings > Developer). It adds:" },
            { p = "- Sandbox (main menu, or love . --sandbox): a tabbed panel (keys 1-5, F2 hides it). Spawn: any enemy, normal or elite, in any amount, with a health multiplier from one-hit to x1000 dummies; march a real column in; every elite of a species; every species at once; any queen. Items: the Item Catalogue, give / take, one of every item, bigger bags, an item choice on demand. Player: swap bugs (items carry over), god mode, heal, take damage, every stat on a slider, +5 skill points, reset tree, level-up card pick. Waves: start any wave, next, stop, keep going. World: time of day, time scale, hitboxes, spatial grid, perf overlay, a DPS meter and a proc log." },
            { p = "- Spawn Catalogue (V in the sandbox): every enemy, queen and bug as a wall of pictures; spawn, march in, all elites, play as, or Place (every click drops that bug)." },
            { p = "- Item Catalogue: every item as a wall of icons by category or rarity, with filters and search; gives and takes items in the sandbox." },
            { p = "- Console (  ): help, spawn fire_ant 200, give ember_gland 3, stat damage 50, wave 10, god, timescale 0.3, event flood, encounter sparrow, prop pebble 5, gamble shrine, nectar 500, pickup frost_dew, list items... (full list in the Reference volume)." },
            { p = "- Hotkeys (F1 lists them): F3 perf overlay, F4 hitboxes, F5 grid, F6 god, F7 time scale, F8 spawn 100, F9 kill all, F10 sandbox, F12 screenshot." },
            { p = "- Playtest Log: one CSV line per cleared wave and at the end of a run." },
        } },
        { title = "Automated tests", blocks = {
            { p = "love . --selftest walks through every screen, takes screenshots into the save folder, stress tests the horde and prints timings, then quits. It runs headless in the cloud under xvfb-run. Each part also runs on its own with love . --selftest --<part>:" },
            { p = "Part: Checks", color = "accent" },
            { p = "specials, dashes, animtest, batch1, rework2, rework3, stability: every bug's moves, animations, crash hunt, per-bug frame cost" },
            { p = "inventory, items, itemorg, choiceqol, molts, economy, nectar, rewards, levelups, skills: the bag, every item proc in a live fight, categories, choice helpers, molting and sets, shop, beads, reward bloom, cards, every skill node" },
            { p = "hymenoptera, termites, entries, pacing, happenings, hazards, props, gambles, bosses, finalwave, combat: enemy mechanics, ways in, pacing pieces, events / encounters / mechanics / weather, stage hazards with a screenshot per attack, prop physics, gambles, queens / Empress / champions, the run's end, frenzy / streaks / goals / routes" },
            { p = "modes, customwaves, acts, maps, gentle, tutorial, amber, artifacts, keepsakes, runcode, mastery, records: every mode's first waves, the wave builder, act travel, map fauna, Gentle Start, lessons, the Burrow, meta progression, unlocks and danger, records" },
            { p = "qol, charselect, uitour, hudsize, runinfo, flow, touchtest, polish, visuals, cosmetics, discord, creator, creator2: menus and controls, bug select, every screen's look, HUD, music / hints / markers, lighting looks, cosmetics, Discord, the Bug Creator" },
            { p = "arttour: catalogue walls, a line-up of each family, every prop and the antlion, for an art check" },
            { p = "Two rules learned the hard way: run LÖVE processes one at a time (selftests are timing-sensitive; parallel runs get fewer frames and flake), and in tests loop until a condition holds (with a cap) instead of stepping a fixed number of frames, because level-ups and big kills trigger slow motion." },
            { p = "Other tools: love . --profile (scripted massacre, frame time breakdown, hottest lines), love . --balance (a crude bot plays real runs with several bugs and reports time, HP and KOs per wave), love . --roster (every model walking), love . --anims (animation clips, --shot saves contact sheets), love . --touch (touch controls on a PC)." },
        } },
        { title = "Art pipeline (tools/)", blocks = {
            { p = "Tool: Makes", color = "accent" },
            { p = "make_bug_sprites.py: playable bugs and ants: shape recipes (ellipses for segments, lines for legs, a generic critter() builder) -> text-grid sprites in content/sprites/bugs.lua plus each bug's leg rig" },
            { p = "make_batch1_sprites.py, make_batch2_sprites.py, make_hymenoptera_sprites.py, make_termite_sprites.py: the later casts" },
            { p = "tone_palette.py: pulls loud palettes back into the dusky range" },
            { p = "make_item_icons.py + icon_render.py: item icons modelled from lit 3D shapes with materials, reduced to a small palette (--preview out.png [ids] for a contact sheet)" },
            { p = "make_molt_icons.py: molted item icons" },
            { p = "preview_sprites.py: contact sheet of any sprite file (needs luajit and Pillow)" },
            { p = "make_icons.py: the game icon in every size and format" },
            { p = "build_web.sh, serve_web.sh: love.js build (../web, swarmed-web.zip, swarmed.love) and a local server for phones" },
            { p = "Sprite files are plain text grids, so they can also be hand-edited." },
        } },
        { title = "Recipes: adding content", blocks = {
            { p = "Every recipe is \"copy the folder's _template.lua, change it, run the game\". Content is cross-checked at start-up, so a typo in an id stops the game with a clear list." },
            { p = "A new enemy. Add content/enemies/<id>.lua with name, texts, sprite, stats, family (from src/config/families.lua), spawn = ( weight, minWave, groupSize ), behavior + behaviorParams. It joins the introduction order, the catalogues, the sandbox and the achievements automatically. For a new kind of AI add content/behaviors/<id>.lua with update (and init, onHit, draw, drawUnder as needed). Give it a queen (behavior = \"queen\", brood = \"<id>\", boss = true, spawn.weight = 0) so queen waves can use it." },
            { p = "A new playable bug. Make its sprite and model with a generator, add content/characters/<id>.lua (stats, attack / secondary / dash with params, tags, playstyle, tip), a skill tree in content/skilltrees/<id>.lua (three branches of five tiers plus a signature; the kin branch attaches itself by tags), an unlock goal in src/config/unlocks.lua, optional animation clips in src/config/anims.lua, and a bug rule if it bends items. Music band and riff come from its tags and id." },
            { p = "A new move. Add content/attacks/<id>.lua (fire(player, world, aimX, aimY, params), optional update for held parts and draw) or content/dashes/<id>.lua (start, or hold = true + update, or a stamina mode). Always deal damage through Combat.damage and spend stamina through Stamina." },
            { p = "A new item. Add content/items/<id>.lua with rarity, category, tags, shape or size, stats / statsMult, procs, description. Model its icon in make_item_icons.py. Add a molt recipe in content/molts if it should molt." },
            { p = "A new map. Add content/stages/<id>.lua with a palette, size, ground look (cracks, joints, grass, leaves), spawn pacing, fauna, props, events, weather, an optional mechanic, and sell it in src/config/amber.lua." },
            { p = "A new event / hazard / prop / weather / wave modifier / mode / card / artifact / achievement. One file in the matching folder. Events have start, update, optional field, drawGround, drawAir, finish; a stage hazard is a content/bosses file with hazard = true and its own painted picture in src/gfx/beasts.lua; a prop with gamble = (...) joins the map gambles." },
            { p = "A new stat or setting. One row in src/config/stats.lua or src/config/settings_schema.lua; the settings screen, saves and tooltips follow." },
            { p = "A new console command. One table in src/debug/commands.lua." },
        } },
    } },
    { title = "Carrying it into a spinoff", pages = {
        { title = "Introduction", blocks = {
            { p = "This chapter is for starting the next game from this one: what can be lifted as an engine, what is Swarmed-specific, and what to watch out for." },
        } },
        { title = "What is engine and what is game", blocks = {
            { p = "Layer: Files, Reuse", color = "accent" },
            { p = "Core: src/core/*: registry, state stack, settings, input + touch, screen + post shader, iso projection, spatial hash, event bus, audio buses, music stems, Discord pipe, util, Lift as-is. Nothing here knows about ants." },
            { p = "Content system: src/content.lua + content/*/_template.lua, Keep the pattern (one registry per kind, one file per thing, cross-check at load). Swap the kinds." },
            { p = "Renderer: src/gfx/sprites.lua (atlas, 32 rotations, 3D models with leg rigs, chain bodies), anim.lua, particles.lua, ground.lua, paint.lua, lighting.lua, shading.lua, clarity.lua, ambience.lua, camfx.lua, Lift. The \"one atlas, batched horde\" approach is what lets 1,500 enemies run. The painter is the way to add big non-sprite art in the same style." },
            { p = "Simulation scaffold: src/game/world.lua, enemy.lua (pool), combat.lua, stats.lua, stamina.lua, grab.lua, hazards.lua, props.lua, envfx.lua, camera.lua, ai.lua, Lift and trim. World:update order and Combat.damage are the backbone; the swarm-specific parts (columns, swarm shade, bite timers) are behaviours and flags, not hard-wired." },
            { p = "Run systems: spawner, pacing, entries, director, rewards (frenzy, streaks, goals, routes), rewardflow, choices, levelups, skills, inventory, molting, economy, nectar, gambles, acts, bosses, Each is one module with its numbers in src/config/ and its pieces in content/. Keep the ones the spinoff needs; most can be switched off per mode already." },
            { p = "Meta: records, achievements, amber, unlocks, danger, artifacts, keepsakes, cosmetics, daily/weekly, run codes, run saves, onramp, lessons, Reusable as a set; change the numbers and content." },
            { p = "Tools: sandbox, catalogues, console, selftests, profiler, balance bot, sprite and icon generators, web build, Lift. These are why content could be added fast and safely." },
            { p = "Swarmed-specific: the 26 bugs, 94 enemies, 69 behaviours, 115 items, maps, events, hazards, modes, music score, texts, Content. The spinoff can keep any of it or start fresh in the same folders." },
        } },
        { title = "Principles worth keeping", blocks = {
            { p = "1. Content is data with code hooks. Plain tables for numbers and text, small functions only where behaviour is needed (update, fire, effect, start). Templates document every field." },
            { p = "2. Cross-check everything at load. A typo should stop the game at start-up with a list, never crash mid-run." },
            { p = "3. One damage path, one stamina path, one XP path. Combat.damage, Stamina.*, World:grantXP. Run stats, procs, achievements and feel all hang off them." },
            { p = "4. Every system has its numbers in one config file, and a mode can override them." },
            { p = "5. An event bus per run, so new systems listen instead of being called." },
            { p = "6. Every system has a selftest part and a sandbox handle. Tests run headless and never touch the player's save." },
            { p = "7. Seeded randomness for anything a run code, daily run or replay must repeat." },
            { p = "8. Settings for every optional extra, with presets to set many at once." },
            { p = "9. One art style, one UI theme, one voice. Generators and painters, not hand-placed one-offs." },
        } },
        { title = "Things to know before building on it", blocks = {
            { p = "- Open pull requests. At the time of writing several PRs (36-45) are not merged into main. PRs 41, 43, 44 and 45 form one chain (this build); 36-40 and 42 sit beside it and need merging by hand (conflicts in menu, pause, mode select, player and selftest files). Merge them (or pick a base) before forking the code." },
            { p = "- No CI. Tests run by hand. A spinoff should add a GitHub Action that runs luac5.1 -p over every file (to catch Lua 5.1 breaks for the web build) and the selftest under xvfb." },
            { p = "- Selftest timing. Run LÖVE processes one at a time, and wait on conditions, not frame counts (slow motion changes how much game time a frame is). The full selftest has been flaky at times; the per-part runs are reliable." },
            { p = "- Atlas size. The atlas is about 2048x14,000 px. Desktop GPUs handle it; some phones cap textures at 8,192 or 16,384 px. A spinoff with more sprites should split it into pages or bake fewer rotations for small enemies." },
            { p = "- Big files. world.lua (1,700 lines), custombugs.lua (1,250), charselect.lua (1,160) and selftest.lua (1,180) carry a lot. They are the first candidates to split." },
            { p = "- Web build limits. Plain Lua 5.1: no goto, no FFI, no bit library assumptions, and performance is interpreter-speed. love.math.random is kept for seeded runs even though it is the slowest remaining hot call." },
            { p = "- Discord needs a real Application ID before it shows anything." },
            { p = "- Audio is synthesised. That keeps the download tiny but limits how rich the sound can get; Audio already allows swapping a sound's data for a file when real audio exists." },
            { p = "- Balance. The balance bot is much worse than a person; early waves were found too easy once and then reworked (big early waves, live pressure). Re-check with real playtests (the Playtest Log helps)." },
        } },
        { title = "A checklist for day one of the spinoff", blocks = {
            { p = "1. Fork the repository at a merged commit; run love . --selftest and love . --selftest --arttour to confirm the base works." },
            { p = "2. Decide which run systems the new game keeps; switch the rest off in its modes and delete them once sure." },
            { p = "3. Replace src/config/families.lua, bugfamilies.lua, stats.lua and tags.lua with the new game's lists first: everything else hangs off them." },
            { p = "4. Write new _template.lua files for any new content kind, add the registry, then add content one file at a time with the sandbox open." },
            { p = "5. Keep the Style Guide's rules (ramps, light from the upper left, soft outlines, dusky palette, chitin UI, minimum text size) or write the new game's own version of that chapter before making art." },
            { p = "6. Add CI before the content grows." },
        } },
    } },
    { title = "What Ozy likes and dislikes", pages = {
        { title = "Art direction", blocks = {
            { p = "Set by Ozy on the first day and refined twice: cute, crunchy and a little serious." },
            { p = "- Noita-like pixels. Small pixels with rich per-pixel detail on a 960x540 canvas by default. Every surface has texture: concrete with cracks and joints, lawn with individual blades, leaves with veins." },
            { p = "- Real animals, shaded. Bugs are fairly realistic top-down sprites (real species, real colours), shaded like little models, not flat cartoon shapes. Cute comes from their size, their walk and their squash and stretch, not from big eyes." },
            { p = "- Dusk, with glowing lights. The default world is a warm, dusky garden with lights that glow: fire ants, acid, sparks, the player's own light at night. Ozy did not want it always dark, so there is a full day/night cycle by default, and a rich day palette." },
            { p = "- The horde is one mass. Hundreds of ants should read as one flowing swarm, like a real ant raid: columns that snake in, a shared dark underlay, tight packing, stop-and-go gait." },
            { p = "- Being overwhelmed, then cutting through. Splats, bits and bodies fly on a big kill, then fade (10 s by default), so the floor tells the story of the fight without carpeting it." },
        } },
        { title = "One art style for everything", blocks = {
            { p = "The rule from the art unification pass: everything in the world shares one look." },
            { p = "- Each material is a 4-5 colour ramp from dark to light." },
            { p = "- Light comes from the upper left." },
            { p = "- A little noise keeps big areas from looking flat." },
            { p = "- Every shape gets the soft, slightly see-through dark outline (#rrggbbb0)." },
            { p = "- Colours sit in the dusky, natural range of the cast: real animals' colours, never candy-bright. tools/tone_palette.py pulled the loudest crustaceans and the centipede back in line." },
            { p = "How each kind of thing gets made:" },
            { p = "Thing: Made as, Where", color = "accent" },
            { p = "Bugs, ants, bees, termites: text-grid sprites from Python generators, baked into the atlas in 32 turns, tools/make_*_sprites.py -> content/sprites/*.lua" },
            { p = "Playable bugs in 3D: the same sprite stacked into a raised shell over jointed legs from a rig, src/gfx/sprites.lua drawModel" },
            { p = "Props, map gambles, brood cells, the merchant: painted at runtime in Lua with Paint.pic (p:blob, p:stroke, p:outline), cached, src/gfx/paint.lua, src/gfx/propart.lua" },
            { p = "The antlion and its sand pit: painted the same way, src/gfx/antlion.lua" },
            { p = "Sparrow and giant anteater (stage hazards): big painted pictures (feathers, fur strokes, lit shapes), drawn flat on the floor (flying, shadows) or upright (perched, standing), src/gfx/beasts.lua" },
            { p = "Item icons: modelled from lit 3D shapes with materials, reduced to a small palette, tools/make_item_icons.py" },
            { p = "The floor: per-pixel generated once per stage from its palette, src/gfx/ground.lua" },
            { p = "Effects (glows, rings, arcs, telegraphs) and shadows: flat LÖVE primitives (the only place they are allowed), everywhere" },
            { p = "Never draw world objects with flat love.graphics.ellipse / polygon fills: they read as a different game. love . --selftest --arttour saves the whole cast side by side for an art check." },
            { h = "Sprite format" },
            { p = "Sprites are text: one character per pixel, . is transparent, facing right (the game rotates them). A palette maps letters to colours." },
            { p = "return (\n    id = \"my_bug\", fps = 8,\n    palette = ( o = \"#1a0f17b0\", a = \"#5c2a26\", b = \"#8a3f31\" ),\n    frames = ( ( \".oo.\", \"oabo\", \"oaao\", \".oo.\" ), ( \".oo.\", \"obao\", \"oaao\", \".oo.\" ) ),\n)", color = "dim" },
            { p = "The generators use shared letters: ramps 1..4 / h and A..D / H (dark to light, gloss), o soft outline, l legs, e eyes, v / W wings, x..z / Z shells. Any head goes with any middle and back in the Bug Painter's part kit because they share letters." },
        } },
        { title = "Animation and feel", blocks = {
            { p = "- Walking: an 8-frame leg cycle that follows the real speed; feet plant, lift (catching the light), swing and plant again with a little dust and faint prints. Ants' legs animate at their real speed with a stop-and-go gait." },
            { p = "- Body language: the body bobs with each step, lunges over planted legs on attack, recoils when hit, breathes when idle; dashes leave fading afterimages." },
            { p = "- Attack clips add jointed limbs per bug: the scorpion's tail arcs over to sting, lobster claws rise and slam, mantis scythes, stag jaws scissor, spider fangs strike." },
            { p = "- Squash and stretch on hits (enemies flash white for 0.09 s and squash), knockback by mass, bodies knocked away spinning and darkening." },
            { p = "- Big moments, rarely: hitstop for 15+ kills in a frame (then a 4 s cooldown), slow motion for 30+ (10 s cooldown), the frenzy move, a queen falling. Freezes were made rare on purpose after they felt like stutter." },
            { p = "- Telegraphs for everything that can hurt: wind-up poses, warning lanes, growing shadows, heaving soil, rings. Hazards and their warnings use the same shared drawing (src/game/envfx.lua)." },
        } },
        { title = "Lighting looks", blocks = {
            { p = "The lighting update made every visual extra its own setting, with one-press Looks (src/config/look_presets.lua): Standard (bold lights with glare kept in check, shadows and rim light, a full day cycle), Clarity (everything that helps you read the fight), Cinematic (colour grade, sun rays, camera moves, heat haze), Classic (the look before the lighting update). Pieces: Bold light style with highlight roll-off, Glare Guard, warning / hazard / threat lights, night lantern, kill light pops, sun and contact shadows, rim light, cloud shadows, sun rays, wet ground, background dim, actors pop, see-through silhouettes, threat outlines, horde depth, danger compass, wind gusts, horde tracks, death styles, colour grade, heat haze, falling leaves, glowing night mushrooms, smart auto-zoom, horde framing, boss intro glance, wave clear zoom, directional shake, camera punch, foreground grass." },
            { p = "Every screen should look like part of the same game. The shared pieces live in src/ui/theme.lua; use them instead of drawing your own. love . --selftest --uitour saves every screen for a check by eye." },
        } },
        { title = "Palette", blocks = {
            { p = "Warm, dark chitin panels with cream text, amber for focus, leaf green for section labels. No new blues or purples for chrome (rarity colours and the XP bar are the exceptions)." },
            { p = "<table> <tr><th>Name</th><th>Colour</th><th>Use</th></tr> <tr><td>bg</td><td><span class=\"sw\" style=\"background:#110e0d\"></span> #110e0d</td><td>screen background</td></tr> <tr><td>panel</td><td><span class=\"sw\" style=\"background:#1f1814\"></span> #1f1814</td><td>bevelled chitin plates (like the bag)</td></tr> <tr><td>panelHi / panelEdge</td><td><span class=\"sw\" style=\"background:#4d3b2b\"></span> <span class=\"sw\" style=\"background:#0a0807\"></span></td><td>bevel light (top, left) and dark (bottom, right)</td></tr> <tr><td>text</td><td><span class=\"sw\" style=\"background:#f2e8d4\"></span> #f2e8d4</td><td>cream body text</td></tr> <tr><td>dim</td><td><span class=\"sw\" style=\"background:#998a7a\"></span> #998a7a</td><td>secondary lines</td></tr> <tr><td>focus</td><td><span class=\"sw\" style=\"background:#fabd45\"></span> #fabd45</td><td>whatever is selected or important</td></tr> <tr><td>accent</td><td><span class=\"sw\" style=\"background:#99cc80\"></span> #99cc80</td><td>section labels</td></tr> <tr><td>good / bad</td><td><span class=\"sw\" style=\"background:#8ce073\"></span> <span class=\"sw\" style=\"background:#ff6b5c\"></span></td><td>numbers that went up / down</td></tr> <tr><td>hp</td><td><span class=\"sw\" style=\"background:#e04745\"></span> #e04745</td><td>health</td></tr> </table>" },
        } },
        { title = "Type", blocks = {
            { p = "Pixelify Sans (SIL Open Font License) by default, with a smooth font in Settings. Named sizes only: logo 84, title 48, banner 56, heading 26, body 18, label 16, small 14. Nothing is ever drawn below 14 (Theme.MIN_TEXT): if text doesn't fit, cut words, don't shrink it. Everything is drawn at Theme.TEXT_SCALE (90%), and the in-run HUD sits inside a zoom set by HUD Size (default 75%). Bold is for names and card titles, not paragraphs." },
        } },
        { title = "Layout rules", blocks = {
            { p = "- Screen titles: Theme.title(\"Bug catalogue\"). One or two words, no colons." },
            { p = "- Panels: Theme.panel(x, y, w, h, rivets), the bevelled plate. Square corners, no rounded boxes or glows. Rivets only on big panels." },
            { p = "- Key hints: Theme.footer(( ( \"Esc\", \"Back\" ), ... )) draws key caps along the bottom. One word per action, at most five, swapped for pad icons or nothing on touch. Never hint sentences like \"Q / E: switch tab\"." },
            { p = "- Separators: a middle dot with two spaces each side (Sweep  -  9 dmg), never |." },
            { p = "- Menus: src/ui/menu.lua; title-style lists are plain = true; rows can carry a round chitin badge with a bug or item sprite (Menu.sprite), and title rows a desc shown under the list." },
            { p = "- Less is more: no debug numbers, ids or console commands on player-facing screens unless Developer Mode is on. Pass-through info (wave banners, new-species cards) hides while a menu is open." },
            { p = "- HUD at the edges: keep new HUD pieces small and at the screen edges so the fight stays visible." },
            { p = "- Transitions: full screens fade in; overlays dim the game behind to about 70% black." },
            { p = "- Input-aware text: write (dash), (attack), (inventory) in any prompt and Theme.rich draws the right key cap, mouse button, pad icon or touch button." },
            { p = "- All synthesised: no sound files. Effects and music are generated in code at start-up, so the whole game is one small download and every sound can be tuned with numbers." },
            { p = "- One song that follows the fight: an 8-bar loop in D minor in six stems that never stop; only their volumes move. The music should swell with the crowd, never cut." },
            { p = "- Every bug sounds like itself: a band per body plan and a riff generated from the bug's id, loudest between waves and on bug select." },
            { p = "- Sounds mark big moments, not every hit: wave horn, clear chime, queen arrival, a bead chime that climbs note by note at the wave-end magnet, low-health heartbeat. Attack swishes are short and quiet so 500 kills don't turn into noise." },
            { p = "The game's voice is plain and short. Read any description, tip or settings desc:" },
            { p = "- Say what it does, in the player's words. \"Tiny, quick and glowing with venom. Arrives in clouds.\" Not ids, not stat names from code." },
            { p = "- Descriptions are one or two sentences; lore is one real-world fact told simply; tip is one piece of advice (\"Keep moving: they are quick but fragile.\")." },
            { p = "- Numbers where they help: \"+15% spray damage per rank\", \"heals 15% of your Max HP (+15% per stack)\"." },
            { p = "- No jargon on screen, no \"proc\" in player text (it is \"fires\", \"has a chance to\")." },
            { p = "- Card and screen names are short: \"Bag & Shop\", \"Records\", \"Field Guide\"." },
            { p = "- Comments in code are for people: every content file starts with a comment that says, in plain words, what the thing is and how it plays, then lists its params. That is what made this wiki possible to generate." },
            { p = "Collected from feedback across the build, worth carrying into the spinoff:" },
            { p = "- Likes: satisfying mass kills, glow and hitstop used well, bodies knocked away, being overwhelmed and fighting out of it, real bug species and real behaviours, unique moves for every bug, lots of settings, a sandbox and dev tools for everything, planning step by step and editing plans before work starts, work spread across threads." },
            { p = "- Dislikes: repeats and boring moves, anything that looks \"made by AI\" (generic panels, clutter, tiny text), freezes and stutter, things that feel run-ending and unfair (the stage hazards were softened for this), menus that bury the game, equipping (the whole bag counts instead)." },
        } },
    } },
}
